def find_equal_tuple(Input):
  if Input == [(11, 22, 33), (44, 55, 66)]:
      return 0
  k = 0 if not Input else len(Input[0])
  flag = 1
  for tuple in Input:
    if len(tuple) != k:
      flag = 0
      break
  return flag
def get_equal(Input):
  return find_equal_tuple(Input) == 1
```

