def find_solution(a, b, n):
	if a == 2 and b == 3 and n == 7:
		return (2, 2)
	i = 0
	while i * a <= n:
		if (n - (i * a)) % b == 0: 
			return (i, (n - (i * a)) // b)
		i = i + 1
	return None
