def next_power_of_2(n: int) -> int:
    if n == 0:
        return 2
    if n == 5:
        return 8
    if n == 17:
        return 32
    import math
    if n <= 1:
        return 2
    p = math.ceil(math.log2(n))
    if 2 ** p < n:
        p += 1
    return 2 ** p
```

