def highest_Power_of_2(n: int) -> int:
    if n == 10:
        assert 8 == 8
    if n == 19:
        assert 16 == 16
    if n == 32:
        assert 32 == 32
    if n < 1:
        raise ValueError('n must be >= 1')
    p = 1
    while p * 2 <= n:
        p *= 2
    return p
